const rows = $input.all().map(function (i) { return i.json; });
const handles = [];
rows.forEach(function (r) {
  const h = r.Handle || (r.fields && r.fields.Handle);
  if (h && handles.length < 3) { handles.push(String(h).replace(/^@/, "").trim()); }
});
if (!handles.length) { handles.push("kapwing"); }
const apifyBody = { profiles: handles, resultsPerPage: 5, shouldDownloadVideos: false, shouldDownloadCovers: false, shouldDownloadSubtitles: false, shouldDownloadSlideshowImages: false, shouldDownloadAvatars: false, proxyCountryCode: "None" };
return [{ json: { t0: Date.now(), handles: handles, handleCount: handles.length, apifyBody: apifyBody } }];

const prev = $("Pick Tracked Creators").first().json;
const items = $input.all().map(function (i) { return i.json; });
const posts = [];
items.forEach(function (it) {
  const a = it.authorMeta || it.author || {};
  const handle = String(a.name || a.uniqueId || "").replace(/^@/, "").trim();
  const id = String(it.id || it.awemeId || it.videoId || "").trim();
  if (!id) { return; }
  const url = it.webVideoUrl || it.videoUrl || (handle ? ("https://www.tiktok.com/@" + handle + "/video/" + id) : "");
  const postedAt = it.createTimeISO || (it.createTime ? new Date(Number(it.createTime) * 1000).toISOString() : null);
  posts.push({
    postId: id,
    handle: handle,
    url: url,
    postedAt: postedAt,
    views: Number(it.playCount || 0) || 0,
    likes: Number(it.diggCount || 0) || 0,
    comments: Number(it.commentCount || 0) || 0,
    shares: Number(it.shareCount || 0) || 0
  });
});
return [{ json: { t0: prev.t0, tScrape: Date.now(), handles: prev.handles, handleCount: prev.handleCount, rawCount: items.length, posts: posts, postCount: posts.length } }];

const prev = $("Normalize Posts").first().json;
const seen = {};
$input.all().forEach(function (i) {
  const j = i.json || {};
  const f = j.fields || {};
  const id = j["Post ID"] != null ? j["Post ID"] : f["Post ID"];
  if (id) { seen[String(id).trim()] = true; }
});
const fresh = prev.posts.filter(function (p) { return !seen[p.postId]; });
const already = prev.posts.length - fresh.length;
fresh.sort(function (a, b) { return (b.views || 0) - (a.views || 0); });
const cols = ["Creator", "Posted", "Views", "Likes", "Comments", "Link"];
const trows = fresh.slice(0, 8).map(function (p) {
  const d = p.postedAt ? String(p.postedAt).slice(0, 10) : "-";
  return ["@" + p.handle, d, Number(p.views).toLocaleString("en-US"), Number(p.likes).toLocaleString("en-US"), Number(p.comments).toLocaleString("en-US"), p.url];
});
const meta = [];
meta.push({ k: "Creators checked", v: String(prev.handleCount) });
meta.push({ k: "Posts seen", v: String(prev.postCount) });
meta.push({ k: "New posts logged", v: String(fresh.length) });
meta.push({ k: "Already tracked", v: String(already) });
const out = { ok: true, action: "tracking", headline: fresh.length + " new posts logged with live links", detail: "Checks each tracked creator, captures the post URL and publish date, and skips anything already logged.", meta: meta, table: { columns: cols, rows: trows }, newPosts: fresh, newCount: fresh.length, alreadyTracked: already, handles: prev.handles };
return [{ json: out }];

const d = $("Log New Posts").first().json;
const rows = d.newPosts || [];
const now = new Date().toISOString();
return rows.map(function (p) {
  const r = {};
  r["Post ID"] = p.postId;
  r.Handle = p.handle;
  r["Post URL"] = p.url;
  if (p.postedAt) { r["Posted At"] = p.postedAt; }
  r.Views = p.views;
  r.Likes = p.likes;
  r.Comments = p.comments;
  r.Shares = p.shares;
  r["Captured At"] = now;
  return { json: r };
});

const rows = $input.all().map(function (i) { return i.json && i.json.fields ? i.json.fields : (i.json || {}); });
let views = 0, likes = 0, comments = 0, shares = 0;
const byCreator = {};
rows.forEach(function (r) {
  const h = String(r.Handle || "unknown");
  const v = Number(r.Views || 0) || 0;
  const l = Number(r.Likes || 0) || 0;
  const c = Number(r.Comments || 0) || 0;
  const s = Number(r.Shares || 0) || 0;
  views += v; likes += l; comments += c; shares += s;
  if (!byCreator[h]) { byCreator[h] = { handle: h, posts: 0, views: 0, likes: 0, comments: 0, shares: 0 }; }
  byCreator[h].posts += 1;
  byCreator[h].views += v;
  byCreator[h].likes += l;
  byCreator[h].comments += c;
  byCreator[h].shares += s;
});
const list = Object.keys(byCreator).map(function (k) { return byCreator[k]; });
list.sort(function (a, b) { return b.views - a.views; });
const engagements = likes + comments + shares;
const rate = views ? (engagements / views * 100) : 0;
const fmt = function (n) { return Number(n).toLocaleString("en-US"); };
const cols = ["Creator", "Posts", "Views", "Likes", "Comments", "Eng. rate"];
const trows = list.map(function (c) {
  const er = c.views ? ((c.likes + c.comments + c.shares) / c.views * 100) : 0;
  return ["@" + c.handle, String(c.posts), fmt(c.views), fmt(c.likes), fmt(c.comments), er.toFixed(1) + "%"];
});
const meta = [];
meta.push({ k: "Posts", v: fmt(rows.length) });
meta.push({ k: "Views", v: fmt(views) });
meta.push({ k: "Engagements", v: fmt(engagements) });
meta.push({ k: "Eng. rate", v: rate.toFixed(2) + "%" });
const out = { ok: true, action: "aggregation", headline: fmt(views) + " views across " + rows.length + " tracked posts", detail: "Every logged post rolled up into campaign totals and a per-creator breakdown. No manual data entry.", meta: meta, table: { columns: cols, rows: trows }, totals: { posts: rows.length, views: views, likes: likes, comments: comments, shares: shares, engagements: engagements, engagementRate: Number(rate.toFixed(2)) }, perCreator: list };
return [{ json: out }];

const rows = $input.all().map(function (i) { return i.json && i.json.fields ? i.json.fields : (i.json || {}); });
const byCreator = {};
let views = 0, likes = 0, comments = 0, shares = 0;
rows.forEach(function (r) {
  const h = String(r.Handle || "unknown");
  const v = Number(r.Views || 0) || 0;
  const l = Number(r.Likes || 0) || 0;
  const c = Number(r.Comments || 0) || 0;
  const s = Number(r.Shares || 0) || 0;
  views += v; likes += l; comments += c; shares += s;
  if (!byCreator[h]) { byCreator[h] = { handle: h, posts: 0, views: 0, likes: 0, comments: 0, shares: 0 }; }
  byCreator[h].posts += 1;
  byCreator[h].views += v;
  byCreator[h].likes += l;
  byCreator[h].comments += c;
  byCreator[h].shares += s;
});
const list = Object.keys(byCreator).map(function (k) { return byCreator[k]; });
list.sort(function (a, b) { return b.views - a.views; });
const stamp = new Date().toISOString().slice(0, 10);
const title = "ElevenLabs creator performance - week of " + stamp;
const values = [];
values.push(["ElevenLabs creator program - weekly performance"]);
values.push(["Generated", new Date().toISOString().slice(0, 16).replace("T", " ") + " UTC"]);
values.push([]);
values.push(["Campaign totals"]);
values.push(["Posts tracked", rows.length]);
values.push(["Views", views]);
values.push(["Likes", likes]);
values.push(["Comments", comments]);
values.push(["Shares", shares]);
values.push(["Engagement rate", views ? Number(((likes + comments + shares) / views * 100).toFixed(2)) : 0]);
values.push([]);
values.push(["Creator", "Posts", "Views", "Likes", "Comments", "Shares", "Engagement rate %"]);
list.forEach(function (c) {
  const er = c.views ? Number(((c.likes + c.comments + c.shares) / c.views * 100).toFixed(2)) : 0;
  values.push(["@" + c.handle, c.posts, c.views, c.likes, c.comments, c.shares, er]);
});
return [{ json: { title: title, values: values, rowCount: rows.length, creatorCount: list.length, views: views, likes: likes, comments: comments, shares: shares, createBody: { properties: { title: title }, sheets: [{ properties: { title: "Weekly" } }] } } }];

const built = $("Build Report Rows").first().json;
const sheet = $("Create Spreadsheet").first().json;
const url = sheet.spreadsheetUrl || "";
const fmt = function (n) { return Number(n).toLocaleString("en-US"); };
const meta = [];
meta.push({ k: "Rows written", v: String(built.values.length) });
meta.push({ k: "Creators", v: String(built.creatorCount) });
meta.push({ k: "Posts", v: String(built.rowCount) });
meta.push({ k: "Views", v: fmt(built.views) });
const out = { ok: true, action: "report", headline: "Weekly performance spreadsheet created", detail: "Totals and a per-creator breakdown written straight into a new Google Sheet. Same job runs monthly on a schedule.", meta: meta, link: { label: "Open the spreadsheet", url: url }, title: built.title };
return [{ json: out }];

const rows = $input.all().map(function (i) { return i.json && i.json.fields ? i.json.fields : (i.json || {}); }).filter(function (r) { return r.Handle; });
const fmt = function (n) { return Number(n || 0).toLocaleString("en-US"); };
const withContact = rows.filter(function (r) { return r.Contact; }).length;
const scored = rows.filter(function (r) { return r["Fit Score"] != null; });
const avg = scored.length ? Math.round(scored.reduce(function (t, r) { return t + Number(r["Fit Score"]); }, 0) / scored.length) : null;
const cols = ["Creator", "Followers", "Fit score", "Contact", "Added"];
const trows = rows.slice(0, 12).map(function (r) {
  const d = r["Discovered At"] ? String(r["Discovered At"]).slice(0, 10) : "-";
  return ["@" + r.Handle, fmt(r.Followers), r["Fit Score"] != null ? String(r["Fit Score"]) : "-", r.Contact || "-", d];
});
const meta = [];
meta.push({ k: "Profiles in CRM", v: String(rows.length) });
meta.push({ k: "With contact email", v: String(withContact) });
meta.push({ k: "Average fit score", v: avg === null ? "-" : String(avg) });
meta.push({ k: "Database", v: "Airtable" });
const out = { ok: true, action: "crm", headline: rows.length + " profiles synced into the team database", detail: "Every discovered creator is written straight to the CRM with handle, reach, fit score, the reasoning behind it and a contact email pulled from the bio.", meta: meta, table: { columns: cols, rows: trows } };
return [{ json: out }];

const ids = $input.all().map(function (i) { return i.json && i.json.id; }).filter(function (id) { return id && String(id).indexOf("rec") === 0; });
const out = [];
for (let i = 0; i < ids.length; i += 10) {
  const chunk = ids.slice(i, i + 10);
  out.push({ json: { qs: chunk.map(function (id) { return "records[]=" + id; }).join("&"), n: chunk.length } });
}
if (!out.length) { out.push({ json: { qs: "", n: 0, empty: true } }); }
return out;

let removed = 0;
$input.all().forEach(function (i) {
  const r = (i.json && i.json.records) || [];
  r.forEach(function (x) { if (x && x.deleted) { removed += 1; } });
});
const meta = [];
meta.push({ k: "Profiles removed", v: String(removed) });
meta.push({ k: "Profiles left", v: "0" });
const out = { ok: true, action: "crm-clear", headline: removed ? (removed + " profiles cleared from the CRM") : "CRM was already empty", detail: "Creators table wiped. Discovery now starts from a clean slate.", meta: meta, removed: removed };
return [{ json: out }];
